+	if whereRaw, ok := fields["where"]; ok {
+		whereMap, isMap := whereRaw.(map[string]any)
+		if !isMap {
+			return nil, ex.Newf("where must be a map")
+		}
+		normalizedWhere, err := normalizeWhere(common, whereMap)
+		if err != nil {
+			return nil, err
+		}
+		if len(normalizedWhere) > 0 {
